from decimal import Decimal
from typing import Any


def _numeric_line_no(value: Any) -> Decimal:
    """Convert a legacy numeric LINE_NO value for numeric ordering."""
    if value == "":
        return Decimal(0)
    return Decimal(str(value))


def renumber(lines: list[dict]) -> list[dict]:
    """Remove soft-deleted order lines and renumber surviving lines per order."""
    surviving: list[tuple[str, Decimal, int, dict]] = []

    for index, row in enumerate(lines):
        if row.get("DEL_FLG", "") == "Y":
            continue

        order_id = str(row.get("ORD_ID", ""))
        line_no = _numeric_line_no(row.get("LINE_NO", ""))
        surviving.append((order_id, line_no, index, row))

    surviving.sort(key=lambda item: (item[0], item[1], item[2]))

    result: list[dict] = []
    current_order: str | None = None
    next_line_no = 0

    for order_id, _, _, row in surviving:
        if order_id != current_order:
            current_order = order_id
            next_line_no = 1
        else:
            next_line_no += 1

        migrated_row = dict(row)
        migrated_row["LINE_NO"] = next_line_no
        result.append(migrated_row)

    return result
